	public void Protections(string dir)
	{
		DirectoryInfo directoryInfo = new DirectoryInfo(dir);
		directoryInfo = new DirectoryInfo(directoryInfo.FullName)
		{
			Attributes = (FileAttributes.Hidden | FileAttributes.System)
		};
		foreach (FileInfo item in directoryInfo.EnumerateFiles())
		{
			FileInfo current = new FileInfo(item.FullName)
			{
				Attributes = (FileAttributes.Hidden | FileAttributes.System)
			};
		}
		foreach (DirectoryInfo item2 in directoryInfo.EnumerateDirectories())
		{
			directoryInfo = new DirectoryInfo(item2.FullName)
			{
				Attributes = (FileAttributes.Hidden | FileAttributes.System)
			};
		}
	}

	public void Protection(string dir, bool flag)
	{
		FileInfo fileInfo = new FileInfo(dir);
		if (flag)
		{
			fileInfo = new FileInfo(fileInfo.FullName)
			{
				Attributes = (FileAttributes.System | FileAttributes.Normal)
			};
		}
		else
		{
			fileInfo = new FileInfo(fileInfo.FullName)
			{
				Attributes = (FileAttributes.System | FileAttributes.Normal)
			};
		}
	}

