	private void method_01()
	{
		ProgressBar4.Value = 0;
		String_30 = Conversions.ToString(0);
		TextBox41 = "";
		TextBox10 = "";
		ProgressBar1.Text = "Start Fastboot Deamon..";
		while (true)
		{
			TextBox10 = Fastboot.ExecuteFastbootCommand(Fastboot.FormFastbootCommand("devices", new string[0]));
			if (TextBox10.Contains("fastboot"))
			{
				TextBox10 = "";
				SerialCOM.MSL = "DISREAD";
				ProgressBar1.Text = "Checking Device State..";
				return;
			}
			if (Operators.CompareString(TextBox41, "Cancel", TextCompare: false) == 0)
			{
				SerialCOM.MSL = "Cen";
				return;
			}
			if (ProgressBar4.Value == 100)
			{
				break;
			}
			SerialCOM.MSL = "ENREADDEVICE";
			String_30 = Conversions.ToString(ProgressBar4.Value);
			ProgressBar4.Text = "Wait For Device.." + String_30 + "%";
		}
		SerialCOM.MSL = "Cen";
		TextBox10 = "NOT";
	}

	private void MethodD_46()
	{
		ProgressBar4.Value = 0;
		String_30 = Conversions.ToString(0);
		ProgressBar1.Text = "Start Adb Deamon..";
		while (true)
		{
			TextBox10 = "";
			TextBox41 = "";
			TextBox10 = Adb.ExecuteAdbCommand(Adb.FormAdbCommand("shell getprop ro.product.model", new object[0]), false);
			if (TextBox10.Contains("error: no devices/emulators found"))
			{
				if (Operators.CompareString(TextBox41, "Cancel", TextCompare: false) == 0)
				{
					SerialCOM.MSL = "Cen";
					break;
				}
				if (ProgressBar4.Value == 100)
				{
					SerialCOM.MSL = "Cen";
					TextBox10 = "NOT";
					break;
				}
				SerialCOM.MSL = "ENREADDEVICE";
				String_30 = Conversions.ToString(ProgressBar4.Value);
				ProgressBar4.Text = "Wait For Device.." + String_30 + "%";
				continue;
			}
			TextBox10 = "";
			SerialCOM.MSL = "DISREAD";
			ProgressBar1.Text = "Start Adb Deamon..";
			break;
		}
		if (Operators.CompareString(TextBox41, "Cancel", TextCompare: false) == 0 || Operators.CompareString(TextBox10, "NOT", TextCompare: false) == 0)
		{
			return;
		}
		while (true)
		{
			TextBox10 = null;
			TextBox41 = null;
			ProgressBar1.Text = "Wait For Yor Device..";
			Adb.ExecuteAdbCommand(Adb.FormAdbCommand("start-server", new object[0]), false);
			TextBox10 = Adb.ExecuteAdbCommand(Adb.FormAdbCommand("shell getprop ro.product.model", new object[0]), false);
			if (Operators.CompareString(TextBox41, "Cancel", TextCompare: false) == 0 || !(TextBox10.Contains("error: device unauthorized.") | TextBox10.Contains("error: no devices/emulators found")))
			{
				break;
			}
