	public void Write(string UFile)
	{
		checked
		{
			byte[] array = new byte[unchecked(MtkTask.Hex_New.Length / 2) - 1 + 1];
			int num = array.Length - 1;
			for (int i = 0; i <= num; i++)
			{
				array[i] = Convert.ToByte(MtkTask.Hex_New.Substring(i * 2, 2), 16);
			}
			try
			{
				File.Delete(UFile);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
			using (StreamWriter streamWriter = File.AppendText(UFile))
			{
				streamWriter.Write("");
				streamWriter.Flush();
				streamWriter.Close();
			}
			File.WriteAllBytes(UFile, array);
		}
	}

	public object Calculating_simlock(string filen)
	{
		MtkTask.Hexx = MtkTask.ByteArrayToString(File.ReadAllBytes(filen));
		if (MtkTask.Hexx.Contains("535433385f30303030") | MtkTask.Hexx.Contains("5354333341303030") | MtkTask.Hexx.Contains("5354333441303030"))
		{
			if (MtkTask.Hexx.Contains("535433385f30303030"))
			{
