	public int MethodD_86(string imeiWithoutCheckDigit)
	{
		char[] array = imeiWithoutCheckDigit.ToCharArray();
		int num = 0;
		int num2 = 0;
		checked
		{
			do
			{
				int num3 = int.Parse(array[num2].ToString());
				num = ((unchecked(num2 % 2) != 0) ? (num + (num3 * 2 - ((num3 > 4) ? 9 : 0))) : (num + num3));
				num2++;
			}
			while (num2 <= 13);
		}
		return checked(10 - unchecked(num % 10)) % 10;
	}

	public MemoryStream ReadFileToMemoryStream(string filePath)
	{
