	private string SendCommand(SerialPort ATPort, string command, int timeout = 3000)
	{
		if (!ATPort.IsOpen)
		{
			return null;
		}
		ATPort.WriteLine(command);
		string text = "";
		Stopwatch stopwatch = new Stopwatch();
		stopwatch.Start();
		do
		{
			Thread.Sleep(50);
			if (!ATPort.IsOpen)
			{
				break;
			}
			text = ATPort.ReadExisting();
		}
		while (!text.Contains("\n" + ClassDevronix.StringO) && !text.Contains("\nERROR") && stopwatch.ElapsedMilliseconds <= timeout);
		Console.WriteLine(text);
		return text;
	}

