	public void MethodD_175()
	{
		try
		{
			string text = MethodD_147("LGE Mobile USB Serial Port");
			text = checked(text.Substring(text.IndexOf("(") + 1, text.Length - 2 - text.IndexOf("("))).Replace(")", "");
			TextBox4.Text = text;
			using SerialPort serialPort = new SerialPort(TextBox4.Text);
			serialPort.RtsEnable = true;
			serialPort.DtrEnable = true;
			serialPort.WriteBufferSize = 921600;
			try
			{
				serialPort.Open();
			}
			catch (UnauthorizedAccessException ex)
			{
				ProjectData.SetProjectError(ex);
				UnauthorizedAccessException ex2 = ex;
				ProjectData.ClearProjectError();
			}
			serialPort.WriteLine("AT%IMEI");
			Stopwatch stopwatch = new Stopwatch();
			stopwatch.Start();
			string text2;
			do
			{
				Thread.Sleep(50);
				text2 = serialPort.ReadExisting();
			}
			while (!text2.Contains("\r\n" + ClassDevronix.StringO + "\r\n") && !text2.Contains("\r\nERROR\r\n") && stopwatch.ElapsedMilliseconds <= 5000);
			if (text2.Contains("\r\n" + ClassDevronix.StringO + "\r\n"))
			{
				IMEI_ID.Text = text2;
				IMEI_ID.Text = IMEI_ID.Text.Remove(0, 7);
				IMEI_ID.Text = IMEI_ID.Text.Remove(0, 1);
				IMEI_ID.Text = IMEI_ID.Text.Remove(0, 1);
				IMEI_ID.Text = IMEI_ID.Text.Remove(0, 1);
				IMEI_ID.Text = IMEI_ID.Text.Remove(0, 1);
				IMEI_ID.Text = IMEI_ID.Text.Replace("\u0003", "");
				IMEI_ID.Text = IMEI_ID.Text.Replace("\r\n", "");
				IMEI_ID.Text = IMEI_ID.Text.Replace(ClassDevronix.StringO, "");
				device_info.imei = IMEI_ID.Text;
			}
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			ProjectData.ClearProjectError();
		}
	}

