	private async void MethodD_198()
	{
		if (!"LM-Q730-LM-Q730AM-LM-Q730QN-LM-Q730QM-LM-Q730UM-LM-Q730TM-LM-Q730MM-LM-Q730QM6".Contains(device_info.model))
		{
			UiManager.wronganswer();
			Guna2MessageDialog1.Text = "We Will Turn Off The Device, Press Volume(+) And Volume(-)";
			Guna2MessageDialog1.Show();
		}
		if (!isMTKClientRunning)
		{
			try
			{
				isMTKClientRunning = true;
				CancellationToken token = cts.Token;
				Adb.ExecuteAdbCommand(Adb.FormAdbCommand("-s " + serialno.Text + " shell reboot -p", new object[0]), false);
				await Task.Run([SpecialName] () => MtkTask.InitAsync(token));
				if (Operators.CompareString(MtkTask.CHECK, "no", TextCompare: false) == 0)
				{
					finshfile();
				}
				else
				{
					ProgressBar1.Text = "Connnect Server...";
					RichTextBox1.SelectionColor = Color.White;
					RichTextBox1.AppendText("- Send Data To Server : ");
					gui.Richlog(ClassDevronix.StringO, Color.FromArgb(0, 85, 207), isBold: false, NextLine: true);
					await Task.Run([SpecialName] () => MtkTask.Data_Update(ClassDevronix.CWQ + "CSC\\", token));
					if (Operators.CompareString(MtkTask.CHECK, "no", TextCompare: false) == 0)
					{
						finshfile();
					}
					else
					{
						finsh();
					}
					ProgressBar1.Text = "Convert CSC Done!";
				}
			}
			catch (OperationCanceledException projectError)
			{
				ProjectData.SetProjectError(projectError);
				isMTKClientRunning = false;
				ProjectData.ClearProjectError();
			}
			isMTKClientRunning = false;
		}
		else
		{
			RichTextBox1.SelectionColor = Color.Red;
			RichTextBox1.AppendText(ClassDevronix.StringF);
			finshfile();
		}
	}

