	private void MethodD_216(RichTextBox richTextBox, string oldText, string newText)
	{
		int selectionStart = richTextBox.SelectionStart;
		int selectionLength = richTextBox.SelectionLength;
		string text = richTextBox.Text;
		int startIndex = 0;
		while (true)
		{
			startIndex = text.IndexOf(oldText, startIndex);
			if (startIndex == -1)
			{
				break;
			}
			richTextBox.Select(startIndex, oldText.Length);
			richTextBox.SelectedText = newText;
			startIndex = checked(startIndex + newText.Length);
		}
		richTextBox.Select(selectionStart, selectionLength);
	}

