	private string AttandVzwCscChange(string HH)
	{
		cdmaTerm.Disconnect();
		string result;
		using (SerialPort serialPort = new SerialPort(TextBox4.Text))
		{
			serialPort.RtsEnable = true;
			serialPort.DtrEnable = true;
			serialPort.WriteBufferSize = serialPort.BaudRate;
			try
			{
				serialPort.Open();
			}
			catch (UnauthorizedAccessException ex)
			{
				ProjectData.SetProjectError(ex);
				UnauthorizedAccessException ex2 = ex;
				RichTextBox1.SelectionColor = Color.Red;
				RichTextBox1.AppendText(ex2.Message);
				serialPort.Close();
				result = "NO";
				ProjectData.ClearProjectError();
				goto end_IL_0016;
			}
			try
			{
				if (SendCommand(serialPort, "AT+PRECONFG=2," + HH, 2000).Contains("+PRECONFG:2,OK"))
				{
					string stringO = ClassDevronix.StringO;
					serialPort.Close();
					result = stringO;
				}
				else
				{
					serialPort.Close();
					result = "NO";
				}
			}
			catch (Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				Exception ex4 = ex3;
				serialPort.Close();
