		}
		return text;
	}

	public static bool MakeRequest()
	{
		bool result;
		try
		{
			HttpWebRequest obj = (HttpWebRequest)WebRequest.Create(String_12 + device_info.imei);
			obj.Method = "POST";
			obj.ContentType = "application/json";
			string s = "{\"query\":\"\",\"variables\":{}}";
			byte[] bytes = Encoding.UTF8.GetBytes(s);
			obj.ContentLength = bytes.Length;
			Stream requestStream = obj.GetRequestStream();
			requestStream.Write(bytes, 0, bytes.Length);
			requestStream.Close();
			HttpWebResponse httpWebResponse = (HttpWebResponse)obj.GetResponse();
			StreamReader streamReader = new StreamReader(httpWebResponse.GetResponseStream());
			string text = streamReader.ReadToEnd();
			SharedUI.RichTextBox7.Text = text;
			streamReader.Close();
			httpWebResponse.Close();
			result = true;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			result = false;
			ProjectData.ClearProjectError();
		}
		return result;
	}

